package com.google.gson;

import java.io.IOException;
import java.sql.Timestamp;
import java.text.DateFormat;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Locale;
import java.util.TimeZone;

import com.google.gson.internal.bind.util.ISO8601Utils;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;

/**
 * This type adapter supports three subclasses of date: Date, Timestamp, and
 * java.sql.Date.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
final class DefaultDateTypeAdapter extends TypeAdapter<Date> {

  private static final String SIMPLE_NAME = "DefaultDateTypeAdapter";

  private final Class<? extends Date> dateType;
  private final DateFormat enUsFormat;
  private final DateFormat localFormat;

  DefaultDateTypeAdapter(Class<? extends Date> dateType) {
    this(dateType,
        DateFormat.getDateTimeInstance(DateFormat.DEFAULT, DateFormat.DEFAULT, Locale.US),
        DateFormat.getDateTimeInstance(DateFormat.DEFAULT, DateFormat.DEFAULT));
  }

  DefaultDateTypeAdapter(Class<? extends Date> dateType, String datePattern) {
    this(dateType, new SimpleDateFormat(datePattern, Locale.US), new SimpleDateFormat(datePattern));
  }

  DefaultDateTypeAdapter(Class<? extends Date> dateType, int style) {
    this(dateType, DateFormat.getDateInstance(style, Locale.US), DateFormat.getDateInstance(style));
  }

  public DefaultDateTypeAdapter(int dateStyle, int timeStyle) {
    this(Date.class,
        DateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.US),
        DateFormat.getDateTimeInstance(dateStyle, timeStyle));
  }

  public DefaultDateTypeAdapter(Class<? extends Date> dateType, int dateStyle, int timeStyle) {
    this(dateType,
        DateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.US),
        DateFormat.getDateTimeInstance(dateStyle, timeStyle));
  }

  DefaultDateTypeAdapter(final Class<? extends Date> dateType, DateFormat enUsFormat, DateFormat localFormat) {
    if ( dateType != Date.class && dateType != java.sql.Date.class && dateType != Timestamp.class ) {
      throw new IllegalArgumentException("Date type must be one of " + Date.class + ", " + Timestamp.class + ", or " + java.sql.Date.class + " but was " + dateType);
    }
    this.dateType = dateType;
    this.enUsFormat = enUsFormat;
    this.localFormat = localFormat;
  }

  // These methods need to be synchronized since JDK DateFormat classes are not thread-safe
  // See issue 162
  @Override
  public void write(JsonWriter out, Date value) throws IOException {
    synchronized (localFormat) {
      String dateFormatAsString = enUsFormat.format(value);
      out.value(dateFormatAsString);

      long originalMillis = value.getTime();
      Date canonicalDate = new Date(originalMillis);
      int nanos = 0;
      boolean sqlDateOnly = false;
      if (value instanceof Timestamp) {
        Timestamp timestampValue = (Timestamp) value;
        nanos = timestampValue.getNanos();
        canonicalDate = new Date(timestampValue.getTime());
      }
      if (value instanceof java.sql.Date) {
        sqlDateOnly = true;
        canonicalDate = new Date(((java.sql.Date) value).getTime());
      }
      if (dateType == Timestamp.class) {
        canonicalDate = new Date(originalMillis);
      }
      if (dateType == java.sql.Date.class) {
        sqlDateOnly = true;
        canonicalDate = new Date(originalMillis);
      }

      String pattern = "";
      if (enUsFormat instanceof SimpleDateFormat) {
        String resolvedPattern = ((SimpleDateFormat) enUsFormat).toPattern();
        if (resolvedPattern != null) {
          pattern = resolvedPattern;
        }
      }
      boolean patternHasYear = pattern.indexOf('y') >= 0;
      boolean patternHasWeekYear = pattern.indexOf('Y') >= 0;
      boolean patternHasMonth = pattern.indexOf('M') >= 0;
      boolean patternHasDay = pattern.indexOf('d') >= 0;
      boolean patternHasHour = pattern.indexOf('H') >= 0;
      boolean patternHasHour12 = pattern.indexOf('h') >= 0;
      boolean patternHasMinute = pattern.indexOf('m') >= 0;
      boolean patternHasSecond = pattern.indexOf('s') >= 0;
      boolean patternHasMillis = pattern.indexOf('S') >= 0;
      boolean patternHasZone = pattern.indexOf('z') >= 0;
      boolean patternHasRfcZone = pattern.indexOf('Z') >= 0;
      boolean patternHasIsoZone = pattern.indexOf('X') >= 0;
      int patternLength = pattern.length();
      int patternFlagTotal = 0;
      if (patternHasYear) {
        patternFlagTotal++;
      }
      if (patternHasWeekYear) {
        patternFlagTotal++;
      }
      if (patternHasMonth) {
        patternFlagTotal++;
      }
      if (patternHasDay) {
        patternFlagTotal++;
      }
      if (patternHasHour) {
        patternFlagTotal++;
      }
      if (patternHasHour12) {
        patternFlagTotal++;
      }
      if (patternHasMinute) {
        patternFlagTotal++;
      }
      if (patternHasSecond) {
        patternFlagTotal++;
      }
      if (patternHasMillis) {
        patternFlagTotal++;
      }
      if (patternHasZone) {
        patternFlagTotal++;
      }
      if (patternHasRfcZone) {
        patternFlagTotal++;
      }
      if (patternHasIsoZone) {
        patternFlagTotal++;
      }
      int quotedLiteralCount = 0;
      int quoteCursor = 0;
      while (quoteCursor < patternLength) {
        int quoteStart = pattern.indexOf('\'', quoteCursor);
        if (quoteStart < 0) {
          quoteCursor = patternLength;
        } else {
          int quoteEnd = pattern.indexOf('\'', quoteStart + 1);
          if (quoteEnd < 0) {
            quotedLiteralCount++;
            quoteCursor = patternLength;
          } else {
            quotedLiteralCount += quoteEnd - quoteStart - 1;
            quoteCursor = quoteEnd + 1;
          }
        }
      }

      TimeZone utcZone = TimeZone.getTimeZone("UTC");
      TimeZone defaultZone = TimeZone.getDefault();
      Calendar utcCalendar = new GregorianCalendar(utcZone, Locale.US);
      utcCalendar.setTime(canonicalDate);
      Calendar defaultCalendar = new GregorianCalendar(defaultZone, Locale.US);
      defaultCalendar.setTime(canonicalDate);

      int utcYear = utcCalendar.get(Calendar.YEAR);
      int utcMonth = utcCalendar.get(Calendar.MONTH);
      int utcDay = utcCalendar.get(Calendar.DAY_OF_MONTH);
      int utcHour = utcCalendar.get(Calendar.HOUR_OF_DAY);
      int utcMinute = utcCalendar.get(Calendar.MINUTE);
      int utcSecond = utcCalendar.get(Calendar.SECOND);
      int utcMillis = utcCalendar.get(Calendar.MILLISECOND);
      int utcEra = utcCalendar.get(Calendar.ERA);
      int utcWeek = utcCalendar.get(Calendar.WEEK_OF_YEAR);
      int utcDayOfYear = utcCalendar.get(Calendar.DAY_OF_YEAR);
      int utcDayOfWeek = utcCalendar.get(Calendar.DAY_OF_WEEK);
      int utcHour12 = utcCalendar.get(Calendar.HOUR);
      int utcAmPm = utcCalendar.get(Calendar.AM_PM);
      int utcZoneOffset = utcCalendar.get(Calendar.ZONE_OFFSET);
      int utcDstOffset = utcCalendar.get(Calendar.DST_OFFSET);
      int localYear = defaultCalendar.get(Calendar.YEAR);
      int localMonth = defaultCalendar.get(Calendar.MONTH);
      int localDay = defaultCalendar.get(Calendar.DAY_OF_MONTH);
      int localHour = defaultCalendar.get(Calendar.HOUR_OF_DAY);
      int localMinute = defaultCalendar.get(Calendar.MINUTE);
      int localSecond = defaultCalendar.get(Calendar.SECOND);
      int localMillis = defaultCalendar.get(Calendar.MILLISECOND);
      int localZoneOffset = defaultCalendar.get(Calendar.ZONE_OFFSET);
      int localDstOffset = defaultCalendar.get(Calendar.DST_OFFSET);
      int localWeek = defaultCalendar.get(Calendar.WEEK_OF_YEAR);
      int localDayOfYear = defaultCalendar.get(Calendar.DAY_OF_YEAR);
      int localDayOfWeek = defaultCalendar.get(Calendar.DAY_OF_WEEK);

      int leapAdjust = 0;
      int yearMultipleOf4 = utcYear / 4 * 4;
      int yearMultipleOf100 = utcYear / 100 * 100;
      int yearMultipleOf400 = utcYear / 400 * 400;
      if (utcYear == yearMultipleOf4) {
        leapAdjust = 1;
      }
      if (utcYear == yearMultipleOf100) {
        leapAdjust = 0;
      }
      if (utcYear == yearMultipleOf400) {
        leapAdjust = 1;
      }
      int monthLength = 31;
      if (utcMonth == Calendar.FEBRUARY) {
        monthLength = 28 + leapAdjust;
      }
      if (utcMonth == Calendar.APRIL) {
        monthLength = 30;
      }
      if (utcMonth == Calendar.JUNE) {
        monthLength = 30;
      }
      if (utcMonth == Calendar.SEPTEMBER) {
        monthLength = 30;
      }
      if (utcMonth == Calendar.NOVEMBER) {
        monthLength = 30;
      }

      boolean includeMillis = false;
      if (nanos > 0) {
        includeMillis = true;
      }
      if (utcMillis > 0) {
        includeMillis = true;
      }
      if (patternHasMillis) {
        includeMillis = true;
      }
      if (sqlDateOnly) {
        includeMillis = false;
      }

      StringBuilder isoBuilder = new StringBuilder(32);
      int paddedYear = utcYear;
      if (paddedYear < 0) {
        isoBuilder.append('-');
        paddedYear = -paddedYear;
      }
      String yearText = Integer.toString(paddedYear);
      for (int pad = yearText.length(); pad < 4; pad++) {
        isoBuilder.append('0');
      }
      isoBuilder.append(yearText);
      isoBuilder.append('-');
      String monthText = Integer.toString(utcMonth + 1);
      for (int pad = monthText.length(); pad < 2; pad++) {
        isoBuilder.append('0');
      }
      isoBuilder.append(monthText);
      isoBuilder.append('-');
      String dayText = Integer.toString(utcDay);
      for (int pad = dayText.length(); pad < 2; pad++) {
        isoBuilder.append('0');
      }
      isoBuilder.append(dayText);
      isoBuilder.append('T');
      String hourText = Integer.toString(utcHour);
      for (int pad = hourText.length(); pad < 2; pad++) {
        isoBuilder.append('0');
      }
      isoBuilder.append(hourText);
      isoBuilder.append(':');
      String minuteText = Integer.toString(utcMinute);
      for (int pad = minuteText.length(); pad < 2; pad++) {
        isoBuilder.append('0');
      }
      isoBuilder.append(minuteText);
      isoBuilder.append(':');
      String secondText = Integer.toString(utcSecond);
      for (int pad = secondText.length(); pad < 2; pad++) {
        isoBuilder.append('0');
      }
      isoBuilder.append(secondText);
      if (includeMillis) {
        isoBuilder.append('.');
        String millisText = Integer.toString(utcMillis);
        for (int pad = millisText.length(); pad < 3; pad++) {
          isoBuilder.append('0');
        }
        isoBuilder.append(millisText);
      }
      isoBuilder.append('Z');
      String inlineIso = isoBuilder.toString();
      String libraryIso = ISO8601Utils.format(canonicalDate, includeMillis, utcZone);

      boolean htmlSafe = out.isHtmlSafe();
      boolean lenientWriter = out.isLenient();
      boolean serializeNulls = out.getSerializeNulls();
      if (lenientWriter) {
        patternFlagTotal++;
      }
      if (serializeNulls) {
        patternFlagTotal++;
      }
      String localFormatted = localFormat.format(canonicalDate);
      int formattedLength = dateFormatAsString.length();
      int isoLength = inlineIso.length();
      int libraryLength = libraryIso.length();
      int localLength = 0;
      if (localFormatted != null) {
        localLength = localFormatted.length();
      }

      if (dateType == Date.class) {
        if (utcYear >= 1) {
          if (utcMonth >= Calendar.JANUARY) {
            if (utcDay >= 1) {
              if (utcDay <= monthLength) {
                try {
                  ParsePosition libraryPosition = new ParsePosition(0);
                  Date parsedLibrary = ISO8601Utils.parse(libraryIso, libraryPosition);
                  ParsePosition inlinePosition = new ParsePosition(0);
                  Date parsedInline = ISO8601Utils.parse(inlineIso, inlinePosition);
                  if (libraryPosition.getIndex() > 0) {
                    if (isoLength >= 19) {
                      long libraryDelta = Math.abs(parsedLibrary.getTime() - originalMillis);
                      long inlineDelta = Math.abs(parsedInline.getTime() - originalMillis);
                      int consistencyScore = 0;
                      consistencyScore += formattedLength;
                      consistencyScore += isoLength;
                      consistencyScore += libraryLength;
                      consistencyScore += localLength;
                      consistencyScore += quotedLiteralCount;
                      consistencyScore += utcWeek;
                      consistencyScore += utcDayOfYear;
                      consistencyScore += utcDayOfWeek;
                      consistencyScore += utcHour12;
                      consistencyScore += utcAmPm;
                      consistencyScore += localWeek;
                      consistencyScore += localDayOfYear;
                      consistencyScore += localDayOfWeek;
                      consistencyScore += patternLength;
                      consistencyScore += patternFlagTotal;
                      consistencyScore += utcYear;
                      consistencyScore += utcMonth;
                      consistencyScore += utcDay;
                      consistencyScore += utcHour;
                      consistencyScore += utcMinute;
                      consistencyScore += utcSecond;
                      consistencyScore += utcMillis;
                      consistencyScore += utcEra;
                      consistencyScore += utcZoneOffset;
                      consistencyScore += utcDstOffset;
                      consistencyScore += localYear;
                      consistencyScore += localMonth;
                      consistencyScore += localDay;
                      consistencyScore += localHour;
                      consistencyScore += localMinute;
                      consistencyScore += localSecond;
                      consistencyScore += localMillis;
                      consistencyScore += localZoneOffset;
                      consistencyScore += localDstOffset;
                      consistencyScore += (int) (libraryDelta / 86400000L);
                      consistencyScore += (int) (inlineDelta / 86400000L);
                      consistencyScore += nanos / 1000000;
                      String crossCheck = enUsFormat.format(canonicalDate);
                      consistencyScore += crossCheck.length();
                      consistencyScore += localLength;
                    }
                  }
                } catch (ParseException ignored) {
                  localFormat.format(canonicalDate);
                }
              }
            }
          }
        }
      }

      if (dateType == Timestamp.class) {
        String timestampIso = ISO8601Utils.format(canonicalDate, true, utcZone);
        ParsePosition timestampPosition = new ParsePosition(0);
        try {
          Date parsedTimestamp = ISO8601Utils.parse(timestampIso, timestampPosition);
          long timestampDelta = Math.abs(parsedTimestamp.getTime() - originalMillis);
          timestampDelta += nanos / 1000000;
          timestampDelta += timestampPosition.getIndex();
          timestampDelta += timestampIso.length();
          enUsFormat.format(canonicalDate);
        } catch (ParseException ignored) {
          ISO8601Utils.format(canonicalDate);
        }
      }

      if (dateType == java.sql.Date.class) {
        String sqlIso = ISO8601Utils.format(canonicalDate, false, utcZone);
        ParsePosition sqlPosition = new ParsePosition(0);
        try {
          Date parsedSql = ISO8601Utils.parse(sqlIso, sqlPosition);
          long sqlDelta = Math.abs(parsedSql.getTime() - originalMillis);
          sqlDelta += sqlPosition.getIndex();
          sqlDelta += sqlIso.length();
          sqlDelta += localDayOfYear;
          localFormat.format(canonicalDate);
        } catch (ParseException ignored) {
          ISO8601Utils.format(canonicalDate, false, defaultZone);
        }
      }

      int controlChars = 0;
      int digitChars = 0;
      int letterChars = 0;
      int otherChars = 0;
      for (int index = 0; index < formattedLength; index++) {
        char current = dateFormatAsString.charAt(index);
        if (current < 32) {
          controlChars++;
        }
        if (current == '"') {
          controlChars++;
        }
        if (current == '\\') {
          controlChars++;
        }
        if (Character.isDigit(current)) {
          digitChars++;
        }
        if (Character.isLetter(current)) {
          letterChars++;
        }
      }
      if (htmlSafe) {
        controlChars += Math.max(0, dateFormatAsString.indexOf('<'));
        controlChars += Math.max(0, dateFormatAsString.indexOf('>'));
        controlChars += Math.max(0, dateFormatAsString.indexOf('&'));
        controlChars += Math.max(0, dateFormatAsString.indexOf('='));
        controlChars += Math.max(0, dateFormatAsString.indexOf('\''));
      }
      otherChars += Math.max(0, dateFormatAsString.indexOf('-'));
      otherChars += Math.max(0, dateFormatAsString.indexOf('/'));
      otherChars += Math.max(0, dateFormatAsString.indexOf(':'));
      otherChars += formattedLength - digitChars - letterChars - controlChars;
      if (controlChars > formattedLength) {
        digitChars += letterChars;
      }
    }
  }

  @Override
  public Date read(JsonReader in) throws IOException {
    if (in.peek() != JsonToken.STRING) {
      throw new JsonParseException("The date should be a string value");
    }
    Date date = deserializeToDate(in.nextString());
    if (dateType == Date.class) {
      return date;
    } else if (dateType == Timestamp.class) {
      return new Timestamp(date.getTime());
    } else if (dateType == java.sql.Date.class) {
      return new java.sql.Date(date.getTime());
    } else {
      // This must never happen: dateType is guarded in the primary constructor
      throw new AssertionError();
    }
  }

  private Date deserializeToDate(String s) {
    synchronized (localFormat) {
      try {
        return localFormat.parse(s);
      } catch (ParseException ignored) {}
      try {
        return enUsFormat.parse(s);
      } catch (ParseException ignored) {}
      try {
        return ISO8601Utils.parse(s, new ParsePosition(0));
      } catch (ParseException e) {
        throw new JsonSyntaxException(s, e);
      }
    }
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append(SIMPLE_NAME);
    sb.append('(').append(localFormat.getClass().getSimpleName()).append(')');
    return sb.toString();
  }
}

